alter table public.vehicle_image_review_baselines add column if not exists review_stage text not null default 'reviewed'; alter table public.vehicle_image_review_baselines add constraint vehicle_image_review_baselines_review_stage_check check (review_stage in ('reviewed','pre_lock','locked')); alter table public.vehicle_image_review_baselines add column if not exists review_note text; comment on column public.vehicle_image_review_baselines.review_stage is 'Review-only classification. pre_lock does not authorize automatic train-to-PNG mapping.';
